import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.DdtnLau3.js";const b=JSON.parse('{"title":"Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md"}'),n={name:"spec/index.md"};function i(s,e,p,c,d,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="specification" tabindex="-1">Specification <a class="header-anchor" href="#specification" aria-label="Permalink to &quot;Specification&quot;">​</a></h1><p>These pages summarize the current Piwork implementation for developers. They adapt the source project&#39;s existing specifications; they do not define a competing API or package format.</p><p>The source was reviewed at commit <a href="https://github.com/pphboy/piwork/tree/326837881f2a3561ae5911dab98a2248d758c2e0" target="_blank" rel="noreferrer"><code>326837881f2a</code></a> on October 6, 2026. The installation guide uses the existing public <code>0.1.0</code> candidate Docker image set; its pinned references and build provenance are recorded separately in the <a href="/piwork/install/0.1.0/README.txt" download>setup metadata</a>. Source changes and image delivery are separate versions.</p><table tabindex="0"><thead><tr><th>Area</th><th>Read here</th><th>Authoritative source</th></tr></thead><tbody><tr><td>Portable Work</td><td><a href="/piwork/spec/work.html">Work Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/docs/work-package-format.md" target="_blank" rel="noreferrer">Package format</a> and <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">portable-work</a></td></tr><tr><td>Managed capabilities</td><td><a href="/piwork/spec/service.html">Service Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/work-services/spec.md" target="_blank" rel="noreferrer">work-services</a> and <a href="https://github.com/pphboy/piwork/blob/main/internal/servicemcp/tools.json" target="_blank" rel="noreferrer">MCP tools</a></td></tr><tr><td>Intelligent execution</td><td><a href="/piwork/spec/harness.html">Harness Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/agent-conversation/spec.md" target="_blank" rel="noreferrer">agent-conversation</a> and <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/piwork-brain/spec.md" target="_blank" rel="noreferrer">piwork-brain</a></td></tr></tbody></table><h2 id="status-labels" tabindex="-1">Status labels <a class="header-anchor" href="#status-labels" aria-label="Permalink to &quot;Status labels&quot;">​</a></h2><ul><li><strong>Current behavior / format:</strong> implemented behavior and source contracts.</li><li><strong>Experimental:</strong> existing behavior whose contracts and user experience are still evolving.</li><li><strong>Future direction:</strong> a product goal that is not an implemented guarantee.</li></ul><p>For mismatches, prefer current implementation over older design notes. <a href="https://github.com/pphboy/piwork/issues" target="_blank" rel="noreferrer">Open an issue</a> with the command, image version, and observed result.</p><h2 id="current-delivery-boundary" tabindex="-1">Current delivery boundary <a class="header-anchor" href="#current-delivery-boundary" aria-label="Permalink to &quot;Current delivery boundary&quot;">​</a></h2><p>Core manages one local Linux Docker Engine through its Unix API. Docker delivery targets <code>linux/amd64</code>, Engine 28+, and Compose 2.24+. The Go CLI has Windows and Linux targets; outstanding native Windows checks are documented in the source <a href="https://github.com/pphboy/piwork/blob/main/docs/cli-platforms.md" target="_blank" rel="noreferrer">CLI platform guide</a>.</p><p>A Work requires ready runtime images and model configuration. Core shutdown stops managed runtime containers while retaining durable state. Closing Desktop or the CLI does not stop the Work.</p>',10)])])}const m=t(n,[["render",i]]);export{b as __pageData,m as default};
